"priority":10},"action":{"type":"timeout"}}},{"initial":{"version":1,"game_id":"00000000-0000-0000-0000-000000000010","config":{"schema_version":2,"name":"terminal-neutral","title":"Terminal neutral","default":false,"playable":false,"board":{"rows":5,"columns":7,"starting_pieces":[{"piece":"token","color":"white","squares":[[0,0]]},{"piece":"token","color":"black","squares":[[4,0]]}]},"pieces":{"token":{"symbols":{"white":"W","black":"B"},"moves":[[0,1],[0,-1]],"attacks":[[0,1],[0,-1]],"jump":false,"repeat":false}},"clock":{"initial_seconds":1,"increment_seconds":2},"exports":[],"appearance":{},"rules":[{"id":"permission","hook":"permits_move","when":{"op":"true"},"effects":[{"op":"permit","params":{}}]},{"id":"resign","hook":"outcome","when":{"op":"compare","relation":"eq","left":{"ref":"event.type"},"right":"resign"},"effects":[{"op":"propose_outcome","params":{"kind":"win","cause":"resign","winner":{"ref":"player.opponent.id"},"priority":10}}]},{"id":"timeout","hook":"outcome","when":{"op":"compare","relation":"eq","left":{"ref":"event.type"},"right":"timeout"},"effects":[{"op":"propose_outcome","params":{"kind":"draw","cause":"timeout","winner":null,"priority":10}}]},{"id":"claim_draw","hook":"outcome","when":{"op":"compare","relation":"eq","left":{"ref":"event.type"},"right":"claim_draw"},"effects":[{"op":"propose_outcome","params":{"kind":"draw","cause":"claim_draw","winner":null,"priority":10}}]}],"quests":[]},"participants":{"1":"00000000-0000-0000-0000-000000000001","-1":"00000000-0000-0000-0000-000000000002"},"started_at_ms":1000,"active_side":1,"board":[{"square":[0,0],"kind":"token","side":1,"moved":false},{"square":[4,0],"kind":"token","side":-1,"moved":false}],"captured":[],"rule_state":{},"special_rights":{},"temporary_targets":{},"clocks":{"remaining_ms":{"1":1000,"-1":1000},"anchor_ms":1000,"increment_ms":2000},"quest_progress":{"00000000-0000-0000-0000-000000000001":{},"00000000-0000-0000-0000-000000000002":{}},"outcome":null,"revision":0,"halfmove