"-1":1000},"anchor_ms":1100,"increment_ms":2000},"quest_progress":{"00000000-0000-0000-0000-000000000001":{},"00000000-0000-0000-0000-000000000002":{}},"outcome":{"kind":"draw","cause":"claim_draw","winner":null,"priority":10},"revision":1,"halfmove_count":0,"events":[{"revision":1,"expected_revision":0,"actor":"00000000-0000-0000-0000-000000000001","action_id":"terminal","at_ms":1100,"move":null,"captured":[],"effects":[],"outcome":{"kind":"draw","cause":"claim_draw","winner":null,"priority":10},"action":{"type":"claim_draw","claim":"claim_draw","intended_move":null}}],"position_history":["{\"active_side\":1,\"board\":[{\"kind\":\"token\",\"moved\":false,\"side\":1,\"square\":[0,0]},{\"kind\":\"token\",\"moved\":false,\"side\":-1,\"square\":[4,0]}],\"rights\":{},\"targets\":{}}"]},"event":{"revision":1,"expected_revision":0,"actor":"00000000-0000-0000-0000-000000000001","action_id":"terminal","at_ms":1100,"move":null,"captured":[],"effects":[],"outcome":{"kind":"draw","cause":"claim_draw","winner":null,"priority":10},"action":{"type":"claim_draw","claim":"claim_draw","intended_move":null}}}]'::jsonb;
  scenario jsonb; initial jsonb; resulting jsonb; event jsonb; original jsonb;
  actor uuid; rejected boolean;
begin
  select array_agg(id order by id) into identities
    from (select id from auth.users order by id limit 3) selected;
  if coalesce(array_length(identities,1),0) < 3 then
    raise exception 'terminal provider gate blocked: three existing identities required';
  end if;
  creator := identities[1]; joiner := identities[2]; outsider := identities[3];
  for scenario in select value from jsonb_array_elements(scenarios) loop
    probe_game := gen_random_uuid();
    scenario := replace(replace(replace(scenario::text,
      '00000000-0000-0000-0000-000000000001',creator::text),
      '00000000-0000-0000-0000-000000000002',joiner::text),
      '00000000-0000-0000-0000-000000000010',probe_game::text)::jsonb;
    initial := scenario->'initial'; resulting := scenario->'state';
    event := scenario->'event'; actor := (event->>'actor')::uuid;
    execute 'set local role service_role';
    perform bgwq.create_game(probe_game,creator,probe_game::text,initial->'config');
    perform bgwq.activate_game(probe_game,joiner,'activate',initial);
    select to_jsonb(g) into original from bgwq.games g where id=probe_game;
    rejected := false;
    begin perform bgwq.commit_revision(probe_game,outsider,0,resulting,event);
    exception when sqlstate '42501' then rejected := true; end;
    if not rejected then raise exception 'outsider terminal action accepted'; end if;

    -- The nested exception rolls back only the injected collision fixture.
    begin
      insert into bgwq.events(game_id,revision,actor,payload)
        values(probe_game,1,actor,'{"probe_collision":true}'::jsonb);
      rejected := false;
      begin perform bgwq.commit_revision(probe_game,actor,0,resulting,event);
      exception when sqlstate '23505' then rejected := true; end;
      if not rejected or (select to_jsonb(g) from bgwq.games g where id=probe_game) <> original then
        raise exception 'terminal event failure changed the game row';
      end if;
      raise exception 'discard collision fixture' using errcode='Z0001';
    exception when sqlstate 'Z0001' then null; end;
    if exists(select 1 from bgwq.events where game_id=probe_game and revision=1) then
      raise exception 'collision fixture survived rollback';
    end if;
    if bgwq.commit_revision(probe_game,actor,0,resulting,event) <> 1
       or bgwq.commit_revision(probe_game,actor,0,resulting,event) <> 1 then
      raise exception 'terminal commit or exact retry failed';
    end if;
    if (select state from bgwq.games where id=probe_game) <> resulting
       or (select count(*) from bgwq.events where game_id=probe_game) <> 2 then
      raise exception 'terminal state and event transcript disagree';
    end if;
    rejected := false;
    begin perform bgwq.commit_revision(probe_game,actor,1,resulting,event || '{"action_id":"new"}'::jsonb);
    exception when sqlstate '55000' then rejected := true; end;
    if not rejected then raise exception 'new terminal action accepted after result'; end if;
    execute 'reset role';
  end loop;
end $probe$;
rollback;
select 'private Supabase resignation, timeout, draw claim and rollback probe passed' as verification;
